def get_attrs(dataset_name: str = "handler-template", **metadata) -> Dict[str, Any]:
    """Build a minimal metadata payload for template-based handlers."""

    attrs = {
        "dataset_name": dataset_name,
        "template_stage": "current-state",
    }
    attrs.update(metadata)
